#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;
long long n, m;

using Matrix = vector<vector<long long>>;

Matrix multiply(const Matrix& a, const Matrix& b) {
    Matrix res(m, vector<long long>(m, 0));
    for (int i = 0; i < m; ++i) {
        for (int k = 0; k < m; ++k) {
            if (a[i][k] == 0) continue;
            for (int j = 0; j < m; ++j) {
                res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    return res;
}

Matrix power(long long exp, Matrix base) {
    if (exp == 1) return base;
    Matrix res = power(exp / 2, base);
    res = multiply(res, res);
    if (exp & 1) res = multiply(res, base);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    if (n < m) {
        cout << 1 << '\n';
        return 0;
    }
    if (n == m) {
        cout << 2 << '\n';
        return 0;
    }

    Matrix mat(m, vector<long long>(m, 0));
    mat[0][0] = 1;
    mat[0][m - 1] = 1;
    for (int i = 1; i < m; ++i) {
        mat[i][i - 1] = 1;
    }

    Matrix result = power(n, mat);
    cout << result[0][0] % MOD << '\n';
    return 0;
}

