#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007LL;

using Matrix = vector<vector<ll>>;

Matrix multiply(const Matrix& a, const Matrix& b, int m) {
    Matrix res(m, vector<ll>(m, 0));
    for (int i = 0; i < m; ++i) {
        for (int k = 0; k < m; ++k) {
            if (a[i][k] == 0) continue;
            for (int j = 0; j < m; ++j) {
                res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    return res;
}

Matrix power(ll exp, const Matrix& base, int m) {
    if (exp == 1) {
        return base;
    }
    Matrix res = power(exp / 2, base, m);
    res = multiply(res, res, m);
    if (exp & 1) {
        res = multiply(res, base, m);
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll n;
    int m;
    cin >> n >> m;

    if (n < m) {
        cout << 1 << '\n';
        return 0;
    }
    if (n == m) {
        cout << 2 << '\n';
        return 0;
    }

    Matrix mat(m, vector<ll>(m, 0));
    mat[0][0] = 1;
    mat[0][m-1] = 1;
    for (int i = 1; i < m; ++i) {
        mat[i][i-1] = 1;
    }

    Matrix res = power(n, mat, m);
    cout << res[0][0] % MOD << '\n';

    return 0;
}
```

